import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { updatePromotionsWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await updatePromotionsWorkflow(req.scope)
    .run({
      input: {
        promotionsData: [{
          id: "promo_123",
          code: "10OFF",
        }],
        additional_data: {
          external_id: "123"
        }
      }
    })

  res.send(result)
}

